import { cn } from "@/lib/utils";
import * as React from "react";
import { Loader2 } from "lucide-react";

export type ButtonVariant = "primary" | "secondary" | "accent" | "outline" | "ghost" | "destructive" | "gradient" | "gradientSecondary" | "gradientAccent";
export type ButtonSize = "sm" | "md" | "lg" | "icon";

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  icon?: React.ReactNode;
  iconPosition?: "left" | "right";
  asChild?: boolean;
  children: React.ReactNode;
}

const Slot = ({ children, ...props }: { children: React.ReactNode } & React.HTMLAttributes<HTMLElement>) => {
  return React.cloneElement(React.Children.only(children) as React.ReactElement, props);
};

const variantClasses: Record<ButtonVariant, string> = {
  primary:
    "bg-primary text-primary-foreground shadow-sm hover:bg-primary-hover hover:shadow-md active:scale-[0.98]",
  secondary:
    "bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary-hover hover:shadow-md active:scale-[0.98]",
  accent:
    "bg-accent text-accent-foreground shadow-sm hover:bg-accent-hover hover:shadow-md active:scale-[0.98]",
  gradient:
    "bg-gradient-to-r from-primary to-violet text-white shadow-lg hover:shadow-glow active:scale-[0.98]",
  gradientSecondary:
    "bg-gradient-to-r from-secondary to-emerald-600 text-white shadow-lg hover:shadow-glow active:scale-[0.98]",
  gradientAccent:
    "bg-gradient-to-r from-accent to-orange-600 text-white shadow-lg hover:shadow-glow-violet active:scale-[0.98]",
  outline:
    "border border-input bg-background hover:bg-accent/10 hover:text-accent hover:border-accent/30 hover:shadow-md active:scale-[0.98]",
  ghost:
    "hover:bg-accent/10 hover:text-accent-foreground active:scale-[0.98]",
  destructive:
    "bg-error text-destructive-foreground shadow-sm hover:bg-error-hover hover:shadow-md active:scale-[0.98]",
};

const sizeClasses: Record<ButtonSize, string> = {
  sm: "h-9 px-3 text-sm gap-1.5",
  md: "h-11 px-5 text-sm gap-2",
  lg: "h-12 px-6 text-base gap-2.5",
  icon: "h-10 w-10 p-0",
};

export function Button({
  className,
  variant = "primary",
  size = "md",
  loading = false,
  icon,
  iconPosition = "left",
  asChild = false,
  children,
  disabled,
  ...props
}: ButtonProps) {
  const classes = cn(
    "inline-flex items-center justify-center rounded-lg font-semibold transition-all duration-200",
    "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2",
    "disabled:pointer-events-none disabled:opacity-60",
    variantClasses[variant],
    sizeClasses[size],
    className
  );

  const renderIcon = () => {
    if (loading) {
      return <Loader2 className="h-4 w-4 animate-spin" aria-hidden="true" />;
    }
    if (icon) {
      return <span className="flex-shrink-0">{icon}</span>;
    }
    return null;
  };

  if (asChild) {
    return (
      <Slot className={classes} {...props}>
        {children}
      </Slot>
    );
  }

  return (
    <button
      className={classes}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      {...props}
    >
      {iconPosition === "left" && renderIcon()}
      {children}
      {iconPosition === "right" && renderIcon()}
    </button>
  );
}

Button.displayName = "Button";
